INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT128-S2-Q4$batch04$, 128, 2, 4, $batch04$Paradox$batch04$, $batch04$In the spring and fall, eastern pipistrelle bats roost deep inside caves. They feed at night on flying insects and must leave the cave to catch their prey. Flying insects are much more abundant on warm nights than on cool ones. Researchers found that many more bats leave the caves on warm nights than on cool nights, even though the temperature within the caves where the bats roost remains virtually the same from one night to the next.$batch04$, $batch04$Which one of the following, if true, most helps to explain the researchers' findings?$batch04$, $batch04$B$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=128 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT128-S2-Q4$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$The researchers studied only female bats, which tended to catch more insects on warm nights than did the male bats.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT128-S2-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$Eastern pipistrelle bats can detect changes in barometric pressure within the caves that correlate closely with changes in temperature outside the caves.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT128-S2-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$Eastern pipistrelle bats are incapable of long periods of sustained activity outside the roosting caves on very cool spring and fall evenings.$batch04$, $batch04$Half Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT128-S2-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Because of the long period of winter inactivity, eastern pipistrelle bats tend to consume more insects per day in the spring and fall than in the summer.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT128-S2-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$During the periods in which the researchers studied the bats, on most evenings over half of the bats left the caves in search of food.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT128-S2-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT128-S2-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$The bats roost deep inside caves, where the temperature barely changes from night to night.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$Many more bats leave the caves on warm nights than on cool ones?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$It makes sense for bats to hunt on warm nights, since that is when insects are out. The puzzle is how they know it is warm outside when the cave feels the same. They need some other signal that tracks the outside temperature.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a way bats inside the cave can tell what the weather is outside.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT128-S2-Q4$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Female bats catching more insects on warm nights does not explain how the bats know it is warm.$batch04$), ($batch04$B$batch04$, $batch04$The bats can sense barometric pressure inside the cave, and that pressure moves with the temperature outside. That is their signal.$batch04$), ($batch04$C$batch04$, $batch04$This is a reason to stay in on cool nights, but it does not explain how a bat in the cave can tell the night is cool.$batch04$), ($batch04$D$batch04$, $batch04$Eating more in spring and fall than in summer does not explain the difference between warm and cool nights.$batch04$), ($batch04$E$batch04$, $batch04$Knowing that more than half the bats left on most evenings says nothing about how they choose which nights.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT128-S2-Q4$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
